CREATE TABLE IF NOT EXISTS books(id TEXT PRIMARY KEY,title TEXT NOT NULL,author TEXT,publisher TEXT,pages INTEGER,description TEXT,cover_key TEXT,category TEXT,featured INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,deleted_at TEXT);
CREATE TABLE IF NOT EXISTS loans(id TEXT PRIMARY KEY,book_id TEXT NOT NULL,full_name TEXT NOT NULL,nickname TEXT NOT NULL,borrowed_at TEXT NOT NULL,due_at TEXT NOT NULL,returned_at TEXT,FOREIGN KEY(book_id) REFERENCES books(id));
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY,book_id TEXT NOT NULL,name TEXT NOT NULL,rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),content TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS push_subscriptions(id TEXT PRIMARY KEY,nickname TEXT NOT NULL,endpoint TEXT NOT NULL UNIQUE,p256dh TEXT NOT NULL,auth TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_books_title ON books(title);CREATE INDEX IF NOT EXISTS idx_loans_nickname ON loans(nickname);CREATE INDEX IF NOT EXISTS idx_loans_due ON loans(due_at,returned_at);
